1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.LocalDate;
7	import java.time.Month;
8	import java.util.HashSet;
9	import java.util.Set;
10	
11	import net.officefloor.plugin.variable.Val;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	
15	/**
16	 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where REGION is
17	 * the region code derived from the owner's postcode (the same derivation the locality shares, see
18	 * {@link OwnerRegion}), FY is the 2-digit fiscal year of the owner's registrationDate (the same YY
19	 * as the {@code fiscalYear} field), HASH8 is the first 8 upper-case hex characters of SHA-256 over
20	 * the owner's normalized (E.164) telephone concatenated with the last name, and CHK is a single Luhn
21	 * check digit computed over the digits of {@code <REGION><FY><HASH8>}.
22	 *
23	 * <p>The identity is therefore a stable function of who the owner is, not of how many owners already
24	 * exist — the old per-city sequence number is gone. This unifies what used to be the separate
25	 * {@code customerCode}, {@code membershipNumber} and {@code checkDigit}.
26	 *
27	 * <p>Should the computed memberId collide with an existing owner's {@code memberId}, it is
28	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
29	 * unique, so distinct owners always end up with distinct member ids.
30	 */
31	public class AssignMemberId {
32	
33	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
34	        String region = OwnerRegion.of(owner);
35	        String fy = fiscalYear2(owner.getRegistrationDate());
36	        String hash8 = hash8(normalizedTelephone(owner.getTelephone()) + owner.getLastName());
37	        String body = region + fy + hash8;
38	        String base = body + luhn(body);
39	        owner.setMemberId(deduplicate(base, existingMemberIds(ownerRepository)));
40	    }
41	
42	    /** The {@code memberId}s already assigned to other owners in the data store. */
43	    private static Set<String> existingMemberIds(OwnerRepository ownerRepository) {
44	        Set<String> ids = new HashSet<>();
45	        for (Owner existing : ownerRepository.findAll()) {
46	            String id = existing.getMemberId();
47	            if (id != null) {
48	                ids.add(id);
49	            }
50	        }
51	        return ids;
52	    }
53	
54	    /**
55	     * Returns {@code base} if it is not already taken; otherwise appends {@code -<n>} with the
56	     * smallest {@code n} of 2 or more that makes it unique.
57	     */
58	    private static String deduplicate(String base, Set<String> taken) {
59	        if (!taken.contains(base)) {
60	            return base;
61	        }
62	        for (int n = 2; ; n++) {
63	            String candidate = base + "-" + n;
64	            if (!taken.contains(candidate)) {
65	                return candidate;
66	            }
67	        }
68	    }
69	
70	    /**
71	     * The last two digits of the fiscal year (1 July - 30 June, named by the calendar year in which
72	     * it ends) of {@code date}, zero-padded. Falls back to the current date's fiscal year when no
73	     * registration date is present.
74	     */
75	    private static String fiscalYear2(LocalDate date) {
76	        LocalDate d = date != null ? date : LocalDate.now();
77	        int fy = d.getMonthValue() >= Month.JULY.getValue() ? d.getYear() + 1 : d.getYear();
78	        return String.format("%02d", Math.floorMod(fy, 100));
79	    }
80	
81	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
82	    private static int luhn(String s) {
83	        int sum = 0;
84	        boolean dbl = true;
85	        for (int i = s.length() - 1; i >= 0; i--) {
86	            char c = s.charAt(i);
87	            if (c < '0' || c > '9') {
88	                continue;
89	            }
90	            int d = c - '0';
91	            if (dbl) {
92	                d *= 2;
93	                if (d > 9) {
94	                    d -= 9;
95	                }
96	            }
97	            sum += d;
98	            dbl = !dbl;
99	        }
100	        return (10 - (sum % 10)) % 10;
101	    }
102	
103	    /**
104	     * The owner's telephone normalized to E.164 (the same way {@link OwnerIdentityKey} does),
105	     * falling back to the trimmed raw value when it cannot form a valid E.164 number. On the create
106	     * path the telephone was already normalized upstream, so this is idempotent.
107	     */
108	    private static String normalizedTelephone(String raw) {
109	        if (raw == null) {
110	            return "";
111	        }
112	        String normalized = E164Telephone.normalize(raw);
113	        return normalized != null ? normalized : raw.trim();
114	    }
115	
116	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
117	    private static String hash8(String s) {
118	        try {
119	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
120	            StringBuilder sb = new StringBuilder();
121	            for (byte b : digest) {
122	                sb.append(String.format("%02X", b));
123	                if (sb.length() >= 8) {
124	                    break;
125	                }
126	            }
127	            return sb.substring(0, 8);
128	        }
129	        catch (NoSuchAlgorithmException ex) {
130	            throw new IllegalStateException("SHA-256 not available", ex);
131	        }
132	    }
133	}
