228	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
229	        if (registrationDate != null
230	                && (fiscalYearOf(java.time.LocalDate.now()) - fiscalYearOf(registrationDate)) > 1) {
231	            points += 3;
232	        }
233	        return points;
