238	     * 0-1 points, 2 for 2-3 points, 3 for 4-5 points, 4 for 6 or more points.
239	     */
240	    default int membershipLevel(Owner owner) {
241	        return levelForPoints(membershipPoints(owner));
242	    }
243	
244	    /**
245	     * As {@link #membershipLevel(Owner)}, but evaluated with the supplied {@code householdMemberCount}
246	     * (see {@link #membershipPointsForHousehold(Owner, int)}).
247	     */
248	    default int membershipLevelForHousehold(Owner owner, int householdMemberCount) {
249	        return levelForPoints(membershipPointsForHousehold(owner, householdMemberCount));
250	    }
